package validations

import (
	"encoding/json"
	"fmt"

	"kena.bot/api-db-go/internal/domain/dbauditlog"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// Request DTOs + parsers for el router `/audit-log`. Vertical SIN
// contrapartida en el Node api-db (el registro de actividad del panel es
// nuevo), así que no hay un zod que mirrorear byte a byte. Se mantiene la
// MISMA forma de fallo que el resto del servicio (400 estructurado, contexto
// ZOD, primer campo que falla vía `zodItemError`) y se reutilizan los
// helpers compartidos del paquete: zodItemError, parseRequiredString,
// parseNullableBoundedString, parseEnumRequired, isJSONNull, jsonKind,
// bodyBindError, coerceLimit, coerceOffset — igual que
// moderation_flow_runs_validations.go.

// auditLogStatusSet + auditLogStatusMsg — el enum cerrado de `status`, mismo
// estilo "Invalid option" del resto (p.ej. flowRunStatusMsg). Construido a
// partir de las constantes de dbauditlog (no de `Statuses`, para que el
// `map[string]bool` que piden parseEnumRequired/el filtro de listado quede
// como literal, igual que flowRunStatusSet).
var auditLogStatusSet = map[string]bool{
	dbauditlog.StatusOK:    true,
	dbauditlog.StatusError: true,
}

const auditLogStatusMsg = `Invalid option: expected one of "ok"|"error"`

// auditLogChangesMaxBytes es el techo de tamaño serializado que
// ParseAuditLogCreate exige a `changes`: un documento libre, pero no
// ilimitado — un blob enorme inflaría silenciosamente la colección (y la
// poda por servidor, que cuenta FILAS, no bytes).
const auditLogChangesMaxBytes = 16 * 1024

// ─── GET /audit-log (list) ─────────────────────────────────────────────────

// ParseAuditLogListQuery mirrors los filtros de
// `GET /audit-log?guild_id=&bot_id=&actor_id=&action=&status=&limit=&offset=`.
// `guild_id` es OBLIGATORIO (a diferencia de dbflowrun.ListParams, donde
// hasta guild_id es opcional); `bot_id`/`actor_id`/`action` son filtros de
// texto libre opcionales; `status` opcional se valida contra el enum
// cerrado; `limit` por defecto 25 (techo 100, vía el coerceLimit
// compartido), `offset` por defecto 0.
func ParseAuditLogListQuery(guildID, botID, actorID, action, status, limitRaw, offsetRaw string) (dbauditlog.ListFilter, int, int, *apierrors.CustomError) {
	if guildID == "" {
		return dbauditlog.ListFilter{}, 0, 0, zodItemError("guild_id is required", "guild_id")
	}
	filter := dbauditlog.ListFilter{GuildID: guildID}
	if botID != "" {
		v := botID
		filter.BotID = &v
	}
	if actorID != "" {
		v := actorID
		filter.ActorID = &v
	}
	if action != "" {
		v := action
		filter.Action = &v
	}
	if status != "" {
		if !auditLogStatusSet[status] {
			return filter, 0, 0, zodItemError(auditLogStatusMsg, "status")
		}
		v := status
		filter.Status = &v
	}

	limitPtr, verr := coerceLimit(limitRaw, 100)
	if verr != nil {
		return filter, 0, 0, verr
	}
	offsetPtr, verr := coerceOffset(offsetRaw)
	if verr != nil {
		return filter, 0, 0, verr
	}
	limit := 25
	if limitPtr != nil {
		limit = *limitPtr
	}
	offset := 0
	if offsetPtr != nil {
		offset = *offsetPtr
	}
	return filter, limit, offset, nil
}

// ─── POST /audit-log (create) ──────────────────────────────────────────────

// ParseAuditLogCreate mirrors el body de creación de una fila:
// `{bot_id,guild_id,actor_id,actor_label?,action,target_type?,target_id?,
// status,changes?,route?}`. `bot_id`/`guild_id`/`actor_id`/`action`/`status`
// son REQUERIDOS; `action` además no puede ir vacía y tiene un techo de 128
// caracteres; el resto son opcionales y nullable. Orden de campos: bot_id,
// guild_id, actor_id, actor_label, action, target_type, target_id, status,
// changes, route — mirrors dbauditlog.Document.
func ParseAuditLogCreate(body []byte) (dbauditlog.CreateInput, *apierrors.CustomError) {
	var raw struct {
		BotID      json.RawMessage `json:"bot_id"`
		GuildID    json.RawMessage `json:"guild_id"`
		ActorID    json.RawMessage `json:"actor_id"`
		ActorLabel json.RawMessage `json:"actor_label"`
		Action     json.RawMessage `json:"action"`
		TargetType json.RawMessage `json:"target_type"`
		TargetID   json.RawMessage `json:"target_id"`
		Status     json.RawMessage `json:"status"`
		Changes    json.RawMessage `json:"changes"`
		Route      json.RawMessage `json:"route"`
	}
	if err := json.Unmarshal(body, &raw); err != nil {
		return dbauditlog.CreateInput{}, bodyBindError(err)
	}

	var in dbauditlog.CreateInput
	var verr *apierrors.CustomError
	if in.BotID, verr = parseRequiredString(raw.BotID, "bot_id", 1, 0); verr != nil {
		return in, verr
	}
	if in.GuildID, verr = parseRequiredString(raw.GuildID, "guild_id", 1, 0); verr != nil {
		return in, verr
	}
	if in.ActorID, verr = parseRequiredString(raw.ActorID, "actor_id", 1, 0); verr != nil {
		return in, verr
	}
	if in.ActorLabel, verr = parseNullableBoundedString(raw.ActorLabel, "actor_label", 0, 0); verr != nil {
		return in, verr
	}
	if in.Action, verr = parseRequiredString(raw.Action, "action", 1, 128); verr != nil {
		return in, verr
	}
	if in.TargetType, verr = parseNullableBoundedString(raw.TargetType, "target_type", 0, 0); verr != nil {
		return in, verr
	}
	if in.TargetID, verr = parseNullableBoundedString(raw.TargetID, "target_id", 0, 0); verr != nil {
		return in, verr
	}
	if in.Status, verr = parseEnumRequired(raw.Status, auditLogStatusSet, auditLogStatusMsg, "status"); verr != nil {
		return in, verr
	}
	if in.Changes, verr = parseAuditLogChanges(raw.Changes); verr != nil {
		return in, verr
	}
	if in.Route, verr = parseNullableBoundedString(raw.Route, "route", 0, 0); verr != nil {
		return in, verr
	}
	return in, nil
}

// parseAuditLogChanges mirrors parseNullableRecord (moderation_infractions_
// validations.go) pero decodifica directo a map[string]any (la forma que
// llevan CreateInput.Changes / Document.Changes — no hay una columna jsonb
// Postgres aguas abajo a la que pasarle los bytes crudos) y ADEMÁS impone el
// techo de auditLogChangesMaxBytes serializados. Ausente o JSON null → nil
// (renderiza como JSON null, igual que `AuditEntry.changes: Record<string,
// unknown> | null`).
func parseAuditLogChanges(raw json.RawMessage) (map[string]any, *apierrors.CustomError) {
	if raw == nil || isJSONNull(raw) {
		return nil, nil
	}
	if jsonKind(raw) != "object" {
		return nil, zodItemError("Invalid input: expected record, received "+jsonKind(raw), "changes")
	}
	if len(raw) > auditLogChangesMaxBytes {
		return nil, zodItemError(fmt.Sprintf("Too big: expected changes to serialize to <=%d bytes", auditLogChangesMaxBytes), "changes")
	}
	var m map[string]any
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, zodItemError("Invalid input: expected record, received "+jsonKind(raw), "changes")
	}
	return m, nil
}

