// ── Flujos de moderación (v4) ───────────────────────────────────────────────
// Espejo manual de `DBGuildSchemas.ts` (mismo motivo que el resto del
// fichero: la versión publicada de `@kena/shared` todavía no lo incluye).
// Se añaden aquí también las dos filas de Postgres (`DBModerationFlowRun`,
// `DBModerationFlowBlockCount`) — no cuelgan de `DBModuleModeration`, pero
// comparten fuente de verdad (contrato §1) y consumidor (`flows.server.ts`).
// El catálogo de bloques (disparadores/condiciones/pasos/variables) NO vive
// aquí: es `flows/catalog/` (mirror de `library-shared/src/moderation-flows`).

/** Cómo se combinan las condiciones de una rama. */
export type DBModerationFlowConditionMode = "and" | "or";

/** Por qué el motor NO ejecutó un flujo que sí encajaba con el disparador. */
export type DBModerationFlowBlockReason =
  | "cooldown" // cooldown por usuario del propio flujo
  | "rate_limit" // techo de ejecuciones por minuto del flujo
  | "channel_filter" // el canal (o su categoría) no pasa el scope
  | "role_filter" // el autor lleva un rol excluido por el scope
  | "bot_author" // autor bot y el flujo los ignora
  | "admin_author" // autor con permiso de gestión y el flujo los ignora
  | "trigger_filter" // los params del disparador no encajan
  | "missing_context" // Discord no mandó la pieza que el flujo necesita
  | "no_branch"; // ninguna rama pasó y no hay «si no» final

/** Resultado de una ejecución que SÍ llegó a correr pasos. */
export type DBModerationFlowRunStatus = "ok" | "partial" | "failed" | "blocked";

/** Dónde escucha el flujo y a quién ignora. Es el nodo «Scope & filters». */
export interface DBModerationFlowScope {
  /** Canales donde el flujo escucha. `all_except` + ids vacío = todos. */
  channels: DBAccessList;
  /** Categorías; se matchea el `parent_id` del canal del evento. */
  categories: DBAccessList;
  /** Roles del autor. `all_except` + ids = «roles ignorados». */
  roles: DBAccessList;
  /** Ignorar autores bot. Nace `true`: es el cortafuegos anti-bucle nº1. */
  ignore_bots: boolean;
  /** Ignorar a quien tenga ManageMessages/Administrator. Nace `true`. */
  ignore_admins: boolean;
  /** Cooldown POR USUARIO entre dos ejecuciones. 0 = sin cooldown. */
  cooldown_seconds: number;
  /** Techo de ejecuciones del flujo por minuto y guild. 0 = sin techo. */
  rate_limit_per_minute: number;
}

/** Una condición de una rama. `negate` es el interruptor «no». */
export interface DBModerationFlowCondition {
  id: string;
  /** Clave del catálogo `MODERATION_FLOW_CONDITIONS`. */
  type: string;
  negate: boolean;
  params: Record<string, unknown>;
}

/** Un paso: acción de moderación, `set_variable`, `wait` o `stop`. */
export interface DBModerationFlowStep {
  id: string;
  /** Clave del catálogo `MODERATION_FLOW_ACTIONS`. */
  type: string;
  params: Record<string, unknown>;
}

/** Rama alternativa. Sin condiciones = el «si no» final; debe ir ÚLTIMA. */
export interface DBModerationFlowBranch {
  id: string;
  condition_mode: DBModerationFlowConditionMode;
  conditions: DBModerationFlowCondition[];
  steps: DBModerationFlowStep[];
}

export interface DBModerationFlow {
  /** `crypto.randomUUID()`, estable de por vida (va en la URL del editor). */
  id: string;
  name: string;
  /** Sólo se ejecutan los `true`. Es el switch «Enabled» de la cabecera. */
  enabled: boolean;
  trigger: { type: string; params: Record<string, unknown> };
  scope: DBModerationFlowScope;
  /** Pasos previos a la bifurcación (típicamente `set_variable`). */
  setup: DBModerationFlowStep[];
  /** Condiciones de la rama RAÍZ (el «If» del editor). Vacío = siempre pasa. */
  condition_mode: DBModerationFlowConditionMode;
  conditions: DBModerationFlowCondition[];
  /** Pasos de la rama raíz (el `then`). */
  steps: DBModerationFlowStep[];
  /** Cadena `else if` / `else`. Ausente o vacío = sin ramas. */
  branches: DBModerationFlowBranch[];
  /**
   * Hasta cuándo se persiste CADA bloqueo como fila propia (ISO-8601).
   * `null` o pasado = sólo contadores agregados. Es el botón «Debug 15 min».
   */
  debug_until: string | null;
  created_at: string;
  updated_at: string;
}

/** Fila de RUNS (Postgres, `moderation.flow_runs`). Sólo lectura desde la
 *  dashboard — quien inserta es el bot. */
export interface DBModerationFlowRun {
  id: string;
  bot_id: string;
  guild_id: string;
  flow_id: string;
  status: DBModerationFlowRunStatus;
  /** Sólo cuando `status === "blocked"`. */
  blocked_reason: DBModerationFlowBlockReason | null;
  /** Id de la rama que ganó; `null` = la raíz. */
  branch_id: string | null;
  steps_total: number;
  steps_run: number;
  duration_ms: number;
  /** Código del primer paso fallido, p.ej. `missing_bot_permission`. */
  error_code: string | null;
  user_id: string | null;
  channel_id: string | null;
  /** Variables finales y resultado por paso. */
  metadata: Record<string, unknown>;
  created_at: string;
}

/** Recuento agregado de bloqueos, por (flujo, motivo, hora). */
export interface DBModerationFlowBlockCount {
  flow_id: string;
  reason: DBModerationFlowBlockReason;
  bucket: string;
  count: number;
}

export interface DBModuleModeration {
  schema_version: number;
  enabled: boolean;
  command_mode: ModerationCommandMode;
  commands_global: DBCommandAccess;
  commands: Record<string, DBConfigurableCommand>;
  mute: DBModuleModerationMute;
  log_channel_id: string | null;
  /** Registrar también las sanciones hechas directamente desde Discord (audit log). */
  track_native_actions: boolean;
  automod: DBModuleModerationAutomod;
  /** Protecciones previas a cualquier sanción (inmunidad y jerarquía). v3. */
  protection: DBModuleModerationProtection;
  /** Escalado automático por infracciones acumuladas. v3. */
  escalation: DBModuleModerationEscalation;
  /** Efectos secundarios de las sanciones (voz, roles, borrado). v3. */
  effects: DBModuleModerationEffects;
  /** Anti-raid: detección de oleadas de entradas. v3. */
  raid: DBModuleModerationRaid;
  /** Filtro de entrada (edad de cuenta, avatar, nombres). v3. */
  gate: DBModuleModerationGate;
  /** Anti-nuke: techo de acciones destructivas por actor y unidad de tiempo. v3. */
  antinuke: DBModuleModerationAntinuke;
  /** Bloqueo de canales (`/lock`, `/unlock` y el lockdown del anti-raid). v3. */
  lockdown: DBModuleModerationLockdown;
  /** Flujos de moderación configurables. v4. */
  flows: DBModerationFlow[];
}

// Inlined helper — equivalente a `createZodObject` de library-shared. El dist CJS
// publicado no lo expone como named export resoluble por el bundle de Vite.
type TypeToZod<T> = {
  [K in keyof T]: z.ZodType<T[K]> | z.ZodType<Exclude<T[K], undefined>>;
};
function createZodObject<T, S extends TypeToZod<T> = TypeToZod<T>>(obj: S) {
  return z.object(obj as Record<string, z.ZodType>) as unknown as z.ZodObject<S>;
}

