// Dependencias entre campos. Con el modo de mute por rol pero sin rol elegido,
// los mutes largos/indefinidos fallan: se bloquea el PATCH.
// Los bloques del v3 NO añaden ninguna: todos degradan solos (el aviso del raid,
// del filtro de entrada y del anti-nuke cae al canal de mod-log cuando no hay
// canal propio; una lista de canales vacía significa "todos"; un escalado
// activado sin peldaños simplemente no hace nada). Bloquear el guardado por eso
// sería el mismo guard falso que se quitó de tempvoice.
export const moderationDependencies: readonly FieldDependency[] = [
  {
    when: "mute.mode",
    is: (v) => v === "role",
    requires: "mute.role_id",
    message: "dashboard.guild.moderation.mute.role.required",
    ui: { tab: "mute", label: "dashboard.guild.moderation.mute.role.required" },
  },
];

// El backend PATCHea vía `$set` con claves top-level opcionales.
// `schema_version` se acepta pero nunca se edita desde el dashboard.
export const sendModerationChangesSchema = moduleModerationSchema
  .omit({ schema_version: true })
  .partial()
  .superRefine(dependencyRefiner(moderationDependencies));
export type SendModerationChangesSchema = z.infer<
  typeof sendModerationChangesSchema
>;

