// 4º argumento de `normalizeModule`: se ejecuta sobre la MEZCLA (defaults +
// documento) justo antes del `safeParse`. Existe por lo mismo que
// `hydrateTempvoiceDefaults`: `deepMerge` NO fusiona elemento a elemento dentro
// de un array, así que un peldaño de escalado guardado antes de que existiera un
// campo llega aquí incompleto, el `safeParse` falla y `normalizeModule` devuelve
// la mezcla en crudo — con la página entera detrás. Rellenar aquí arregla las
// dos cosas: no hay `undefined` que leer y el parseo vuelve a pasar.
export const hydrateModerationDefaults = (
  merged: ModuleModerationSchema,
): void => {
  // Los `as Partial<…>` son a propósito: el tipo dice que los campos están, pero
  // lo que llega de Mongo puede no tenerlos — es justo lo que hay que detectar.
  for (const rule of merged.escalation?.rules ?? []) {
    const draft = rule as Partial<DBModerationEscalationRule>;
    const fallback = defaultEscalationRule();
    if (draft.threshold == null) draft.threshold = fallback.threshold;
    if (draft.action == null) draft.action = fallback.action;
    if (draft.duration_ms == null) draft.duration_ms = fallback.duration_ms;
  }
  // `limits` es un mapa: las claves que el documento no traiga NO las repone
  // `deepMerge` si el propio mapa viene sustituido, y una acción vigilada nueva
  // (v3 trae trece) dejaría el select de la UI atado a un `undefined`.
  const limits = merged.antinuke?.limits;
  if (!limits) return;
  for (const action of MODERATION_NUKE_ACTIONS) {
    const current = limits[action];
    if (current == null) {
      limits[action] = defaultNukeLimit(action);
      continue;
    }
    const draft = current as Partial<DBModerationNukeLimit>;
    const fallback = defaultNukeLimit(action);
    if (draft.enabled == null) draft.enabled = fallback.enabled;
    if (draft.max == null) draft.max = fallback.max;
    if (draft.window_ms == null) draft.window_ms = fallback.window_ms;
    if (draft.punishment == null) draft.punishment = fallback.punishment;
  }
};

import * as z from "zod";
import { accessListSchema } from "../moderation-schema";

// `defaultFlowScope`/`newFlow` son del CATÁLOGO (contrato §2.6, `catalog/validate.ts`):
// construyen un `DBModerationFlow` completo con defaults válidos y conocen el
// catálogo de disparadores (`buildDefaultParams` rellena `trigger.params`).
// Este fichero NO los reimplementa — sólo añade la capa zod (forma/tipos) por
// encima y los re-exporta para que el resto de la feature (`flows.server.ts`,
// `store/`, las rutas) tenga un único punto de entrada. La validación de
// REGLAS de negocio contra el catálogo (`validateFlow`) vive también en
// `./catalog`, es una capa distinta de la de aquí.
export { defaultFlowScope, newFlow } from "./catalog";

/** Ámbito y filtros de un flujo («Scope & filters» del editor). */
export const flowScopeSchema = z.object({
  channels: accessListSchema,
  categories: accessListSchema,
  roles: accessListSchema,
  ignore_bots: z.boolean(),
  ignore_admins: z.boolean(),
  cooldown_seconds: z.number().int().min(0),
  rate_limit_per_minute: z.number().int().min(0),
});

/**
 * `params` se valida como objeto libre A PROPÓSITO — quien conoce su forma es
 * el catálogo (`MODERATION_FLOW_CONDITIONS`/`MODERATION_FLOW_ACTIONS`), que la
 * valida con `validateFlowParams`. Reescribir esas reglas aquí en zod sería una
 * tercera copia que se separaría de las otras dos. Mismo motivo que
 * `automation-schema.ts`.
 */
const flowParamsSchema = z.record(z.string(), z.unknown());

export const flowConditionSchema = z.object({
  id: z.string().min(1),
  // Clave del catálogo `MODERATION_FLOW_CONDITIONS` — string libre aquí: quien
  // valida que la clave EXISTA es `validateFlow`, no este schema.
  type: z.string().min(1),
  negate: z.boolean(),
  params: flowParamsSchema,
});

export const flowStepSchema = z.object({
  id: z.string().min(1),
  // Clave del catálogo `MODERATION_FLOW_ACTIONS`.
  type: z.string().min(1),
  params: flowParamsSchema,
});

/** Rama alternativa. Sin condiciones = el «si no» final; debe ir ÚLTIMA (lo
 *  comprueba `validateFlow`, no este schema). */
export const flowBranchSchema = z.object({
  id: z.string().min(1),
  condition_mode: z.enum(["and", "or"]),
  conditions: z.array(flowConditionSchema),
  steps: z.array(flowStepSchema),
});

/**
 * Zod ESTRUCTURAL de UN `DBModerationFlow` — valida forma y tipos (al leer de
 * Mongo, o antes de guardar desde el editor). NO conoce el catálogo: un flujo
 * cuyo `trigger.type` ya no exista sigue siendo "válido" para este schema — lo
 * detecta `validateFlow` (`getAvailableConditions`/`_actions` devuelven listas
 * vacías) y se marca en el editor, no aquí. Dos capas independientes a
 * propósito, igual que `automationSchema` frente a `validateAutomation`.
 */
export const flowSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1).max(100),
  enabled: z.boolean(),
  trigger: z.object({
    type: z.string().min(1),
    params: flowParamsSchema,
  }),
  scope: flowScopeSchema,
  setup: z.array(flowStepSchema),
  condition_mode: z.enum(["and", "or"]),
  conditions: z.array(flowConditionSchema),
  steps: z.array(flowStepSchema),
  branches: z.array(flowBranchSchema),
  debug_until: z.string().nullable(),
  created_at: z.string(),
  updated_at: z.string(),
});

export type FlowSchema = z.infer<typeof flowSchema>;

// Tipos re-exportados: el resto de la feature de flujos (`flows.server.ts`,
// `store/`, y los componentes de editor/runs) importan de AQUÍ y no reabren
// `../moderation-schema` directamente — este fichero es el punto de entrada.
export type {
  DBModerationFlow,
  DBModerationFlowBlockCount,
  DBModerationFlowBlockReason,
  DBModerationFlowBranch,
  DBModerationFlowCondition,
  DBModerationFlowConditionMode,
  DBModerationFlowRun,
  DBModerationFlowRunStatus,
  DBModerationFlowScope,
  DBModerationFlowStep,
} from "../moderation-schema";

package dbguild

import (
	"go.mongodb.org/mongo-driver/v2/bson"
)

// This file mirrors the `DBModuleModeration` family in
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. The field
// ORDER of every struct matches the corresponding zod object schema in
// `apis/api-db/src/domain/zod-schemas/mongo/guild-schema.ts` (which happens to
// match the TS interface order): the Node GET response is produced by
// `moduleModerationSchema.parse(...)`, which normalises key order to the
// schema-definition order — so matching that order keeps the JSON body
// byte-for-byte identical.
//
// The moderation module is per-guild moderation CONFIG only (command mode +
// per-command access/DM, the hybrid-mute strategy, the mod-log channel, the
// AutoMod ruleset and — from v3 — the protection / escalation / effects / raid
// / gate / antinuke / lockdown blocks). The concrete sanctions (infractions)
// live in Postgres (`moderation.infractions`), NOT here.
//
// Nullable fields (`string | null` in TS) use pointer types so JSON encoding
// emits `null` (not `""`) for the unset variant: `log_channel_id`,
// `mute.role_id`, each command's `dm_embed.color`, and the v3
// `raid.alert_*`/`gate.alert_channel_id`/`antinuke.alert_*`. Collection fields
// (`[]string`, `Record<...>`) are never `omitempty`: a present-but-empty value
// must serialise as `[]` / `{}`, never `null`. `NormalizeModeration` backfills
// nil collections so the invariant holds for docs decoded from Mongo/Redis.
//
// Los defaults viven en ESTE paquete (y no en `mocks`) por dos razones: el
// paquete `mocks` ya importa `dbguild`, así que la migración no podría llamarlo
// sin ciclo; y así el seed del documento nuevo y el backfill del documento
// viejo comparten UNA sola fuente de verdad. Mismo patrón que
// `DefaultMusicCommands`.

// ModerationCommandMode mirrors `ModerationCommandMode` (`"slash" | "prefix" |
// "both"`) — how the moderation commands may be invoked (same pattern as
// tempvoice).
type ModerationCommandMode string

const (
	ModerationCommandModeSlash  ModerationCommandMode = "slash"
	ModerationCommandModePrefix ModerationCommandMode = "prefix"
	ModerationCommandModeBoth   ModerationCommandMode = "both"
)

// ModerationMuteMode mirrors `ModerationMuteMode` (`"auto" | "timeout" |
// "role"`) — the hybrid-mute application strategy (native timeout ≤28d / silence
// role).
type ModerationMuteMode string

const (
	ModerationMuteModeAuto    ModerationMuteMode = "auto"
	ModerationMuteModeTimeout ModerationMuteMode = "timeout"
	ModerationMuteModeRole    ModerationMuteMode = "role"
)

// ModerationAccessMode mirrors `DBAccessMode` (`"only" | "all_except"`) — the
// mode of a command access list. `only` = allowlist, `all_except` = denylist.
// Defined locally (not shared with tempvoice) to keep the verticals decoupled,
// matching how tempvoice/modmail each define their own.
type ModerationAccessMode string

const (
	ModerationAccessOnly      ModerationAccessMode = "only"
	ModerationAccessAllExcept ModerationAccessMode = "all_except"
)

// AutomodAction mirrors `AutomodAction` (`"delete" | "delete_warn" |
// "delete_timeout" | "delete_kick" | "delete_ban"`) — what the AutoMod does when
// a rule fires: delete only, delete + DM warning, delete + tempmute
// (`timeout_ms`), delete + kick, or delete + ban. Los tres primeros son los del
// v2 y siguen siendo válidos: la ampliación del v3 es ADITIVA y ningún
// documento existente necesita migrarse por ella.
type AutomodAction string

const (
