	ModerationNukeMemberKick       ModerationNukeAction = "member_kick"
	ModerationNukeMemberPrune      ModerationNukeAction = "member_prune"
	ModerationNukeMemberRoleUpdate ModerationNukeAction = "member_role_update"
	ModerationNukeWebhookCreate    ModerationNukeAction = "webhook_create"
	ModerationNukeEmojiDelete      ModerationNukeAction = "emoji_delete"
	ModerationNukeGuildUpdate      ModerationNukeAction = "guild_update"
