// ModerationNukePunishment mirrors `ModerationNukePunishment` — el castigo que
// recibe el causante al reventar un límite del anti-nuke.
type ModerationNukePunishment string

const (
	ModerationNukePunishAlert      ModerationNukePunishment = "alert"
	ModerationNukePunishStripRoles ModerationNukePunishment = "strip_roles"
	ModerationNukePunishKick       ModerationNukePunishment = "kick"
	ModerationNukePunishBan        ModerationNukePunishment = "ban"
)

// ModerationNukePunishmentOrInherit mirrors `ModerationNukePunishmentOrInherit`
// — igual que `ModerationNukePunishment` más `inherit` (= usar el castigo
// global del bloque). Go no tiene uniones de tipos: los cuatro valores
