1	/**
2	 * ESPEJO de `libraries/library-shared/src/moderation-flows/validate.ts`.
3	 *
4	 * `dashboard/` NO es miembro del workspace pnpm: instala `@kena/shared` del
5	 * registro PRIVADO (un tarball versionado), no la copia local del monorepo.
6	 * Republicar ese paquete para que incluya este catálogo es un despliegue en DOS
7	 * pasos (primero `@kena/shared`, luego la dashboard), así que este fichero es
8	 * una copia MANTENIDA A MANO del canónico — no se puede hacer todavía
9	 * `export * from "@kena/shared/moderation-flows"`.
10	 *
11	 * `catalog-mirror.test.ts` compara este fichero con el canónico BYTE A BYTE
12	 * (salvo esta cabecera y la línea de import de `@kena/shared/automation`) y
13	 * FALLA si divergen. Si tocas uno, toca el otro.
14	 */
15	
16	import { MODERATION_FLOW_ACTIONS } from "./actions.js";
17	import { MODERATION_FLOW_CONDITIONS } from "./conditions.js";
18	import { MODERATION_FLOW_TRIGGERS } from "./triggers.js";
19	import {
20		MODERATION_FLOW_ACTION_KEYS,
21		MODERATION_FLOW_CONDITION_KEYS,
22		MODERATION_FLOW_TRIGGER_KEYS,
23		type ModerationFlowActionDef,
24		type ModerationFlowActionType,
25		type ModerationFlowConditionDef,
26		type ModerationFlowConditionInstance,
27		type ModerationFlowConditionType,
28		type ModerationFlowContextKey,
29		type ModerationFlowInstance,
30		type ModerationFlowParam,
31		type ModerationFlowScopeInstance,
32		type ModerationFlowStepInstance,
33		type ModerationFlowTriggerType
34	} from "./types.js";
35	
36	/**
37	 * Validación de flujos de moderación contra el catálogo. La usan las DOS
38	 * puntas: la dashboard para no dejar publicar un flujo roto, y el módulo para
39	 * no ejecutar uno que llegue roto de todos modos (un documento viejo, una
40	 * edición a mano en Mongo, un catálogo recortado).
41	 *
42	 * Devuelve una lista de problemas en vez de lanzar: la dashboard los pinta
43	 * todos a la vez junto a su bloque, que es lo que espera quien está montando
44	 * el flujo.
45	 */
46	
47	export type ModerationFlowIssueCode =
48		| "unknown_trigger"
49		| "missing_context"
50		| "missing_param"
51		| "bad_regex"
52		| "out_of_range"
53		| "bad_format"
54		| "unreachable_branch"
55		| "empty_branch"
56		| "duplicate_variable"
57		| "empty_flow";
58	
59	export interface ModerationFlowIssue {
60		/** Ruta del campo, tal cual la usa la dashboard para anclar el error. */
61		path: string;
62		code: ModerationFlowIssueCode;
63		/**
64		 * Identificador estable y específico de ESTE mensaje concreto — a
65		 * diferencia de `code`, que agrupa varios mensajes distintos bajo el mismo
66		 * contrato con el motor (p. ej. `bad_format` cubre «tiene que ser texto»,
67		 * «tiene que ser un número», «no tiene el formato correcto»… con textos y
68		 * piezas a interpolar distintos). La dashboard lo usa para traducir vía
69		 * `dashboard.guild.moderation.flows.issue.<messageKey>`
70		 * (`flowIssueMessage` en `catalog-i18n.ts`).
71		 */
72		messageKey: string;
73		/**
74		 * Piezas para interpolar en la traducción de `messageKey` (el nombre del
75		 * param, el mínimo/máximo exigido…). Ausente cuando el mensaje no
76		 * interpola nada.
77		 */
78		values?: Record<string, string | number>;
79		/** Mensaje en castellano, listo para enseñar. */
80		message: string;
81	}
82	
83	const SNOWFLAKE = /^\d{17,20}$/;
84	
85	// ─── Guardas de tipo ──────────────────────────────────────────────────────────
86	
87	export const isModerationFlowTriggerType = (value: string): value is ModerationFlowTriggerType =>
88		(MODERATION_FLOW_TRIGGER_KEYS as readonly string[]).includes(value);
89	
90	export const isModerationFlowConditionType = (value: string): value is ModerationFlowConditionType =>
91		(MODERATION_FLOW_CONDITION_KEYS as readonly string[]).includes(value);
92	
93	export const isModerationFlowActionType = (value: string): value is ModerationFlowActionType =>
94		(MODERATION_FLOW_ACTION_KEYS as readonly string[]).includes(value);
95	
96	// ─── Compatibilidad disparador ↔ bloque ───────────────────────────────────────
97	
98	/**
99	 * Condiciones que se pueden usar con este disparador: las que no piden nada
100	 * que el disparador no traiga. `triggerType` va sin tipar porque quien llama
101	 * normalmente tiene un `string` sin validar (el `type` crudo del documento).
102	 */
103	export function getAvailableConditions(triggerType: string): ModerationFlowConditionDef[] {
104		if (!isModerationFlowTriggerType(triggerType)) return [];
105		const provided = new Set<ModerationFlowContextKey>(MODERATION_FLOW_TRIGGERS[triggerType].provides);
106		return Object.values(MODERATION_FLOW_CONDITIONS).filter((c) => c.requires.every((k) => provided.has(k)));
107	}
108	
109	/** Pasos que se pueden usar con este disparador. Mismo criterio. */
110	export function getAvailableActions(triggerType: string): ModerationFlowActionDef[] {
111		if (!isModerationFlowTriggerType(triggerType)) return [];
112		const provided = new Set<ModerationFlowContextKey>(MODERATION_FLOW_TRIGGERS[triggerType].provides);
113		return Object.values(MODERATION_FLOW_ACTIONS).filter((a) => a.requires.every((k) => provided.has(k)));
114	}
115	
116	// ─── Parámetros ───────────────────────────────────────────────────────────────
117	
118	/** Objeto de parámetros inicial de un bloque recién añadido, con sus defaults. */
119	export function buildDefaultParams(params: ModerationFlowParam[]): Record<string, unknown> {
120		const out: Record<string, unknown> = {};
121		for (const param of params) {
122			if (param.default !== undefined) {
123				out[param.key] = param.default;
124				continue;
125			}
126			// Sin default declarado. Los campos de lista necesitan un array desde el
127			// principio para que el control sepa qué renderizar; el resto se deja
128			// AUSENTE para que `missing_param` lo cace si hacía falta.
129			if (param.type === "text_list" || param.type.endsWith("_list") || (param.type === "select" && param.multiple)) {
130				out[param.key] = [];
131			} else if (param.type === "boolean") {
132				out[param.key] = false;
133			}
134		}
135		return out;
136	}
137	
138	/** ¿Cuenta como «sin rellenar»? `false` y `0` NO — son valores legítimos. */
139	const isEmpty = (value: unknown): boolean =>
140		value === undefined || value === null || value === "" || (Array.isArray(value) && value.length === 0);
141	
142	function checkOne(param: ModerationFlowParam, value: unknown, path: string): ModerationFlowIssue[] {
143		const issues: ModerationFlowIssue[] = [];
144		const at = `${path}.${param.key}`;
145		// `paramKey` se inyecta AQUÍ, en el único punto por el que pasan todos los
146		// fallos de un param, en vez de repetirlo en los quince `fail(...)` de
147		// abajo. Lo necesita la dashboard: `values.param` es el rótulo del
148		// catálogo, o sea CASTELLANO, y sin la clave no hay forma de volver a
149		// traducirlo — el mensaje saldría «"Motivo" is required.» en inglés. El
150		// motor del bot ignora `values` y sigue registrando `message` tal cual.
151		const fail = (
152			code: ModerationFlowIssueCode,
153			messageKey: string,
154			message: string,
155			values?: Record<string, string | number>
156		) =>
157			issues.push({
158				path: at,
159				code,
160				messageKey,
161				message,
162				values: values && "param" in values ? { ...values, paramKey: param.key } : values
163			});
164	
165		if (isEmpty(value)) {
166			if (param.required) {
167				fail("missing_param", "param_required", `«${param.label}» es obligatorio.`, { param: param.label });
168			}
169			return issues;
170		}
171	
172		switch (param.type) {
173			case "text_list": {
174				if (!Array.isArray(value) || value.some((v) => typeof v !== "string")) {
175					fail("bad_format", "param_not_text_list", `«${param.label}» tiene que ser una lista de textos.`, {
176						param: param.label
177					});
178					break;
179				}
180				if (param.min !== undefined && value.length < param.min) {
181					fail("out_of_range", "param_min_items", `«${param.label}» necesita al menos ${param.min} valores.`, {
182						param: param.label,
183						min: param.min
184					});
185				}
186				if (param.max !== undefined && value.length > param.max) {
187					fail("out_of_range", "param_max_items", `«${param.label}» admite como mucho ${param.max} valores.`, {
188						param: param.label,
189						max: param.max
190					});
191				}
192				break;
193			}
194	
195			case "text":
196			case "long_text":
197			case "emoji":
198			case "counter":
199			case "automation":
200			case "regex":
201			case "color": {
202				if (typeof value !== "string") {
203					fail("bad_format", "param_not_text", `«${param.label}» tiene que ser texto.`, { param: param.label });
204					break;
205				}
206				if (param.min !== undefined && value.length < param.min) {
207					fail("out_of_range", "param_min_length", `«${param.label}» necesita al menos ${param.min} caracteres.`, {
208						param: param.label,
209						min: param.min
210					});
211				}
212				if (param.max !== undefined && value.length > param.max) {
213					fail("out_of_range", "param_max_length", `«${param.label}» admite como mucho ${param.max} caracteres.`, {
214						param: param.label,
215						max: param.max
216					});
217				}
218				if (param.pattern && !new RegExp(param.pattern).test(value)) {
219					fail("bad_format", "param_bad_pattern", `«${param.label}» no tiene el formato correcto.`, {
220						param: param.label
221					});
222				}
223				if (param.type === "regex") {
224					try {
225						new RegExp(value, "u");
226					} catch {
227						fail("bad_regex", "param_bad_regex", `«${param.label}» no es una expresión regular válida.`, {
228							param: param.label
229						});
230					}
231				}
232				break;
233			}
234	
235			case "number":
236			case "duration": {
237				if (typeof value !== "number" || !Number.isFinite(value)) {
238					fail("bad_format", "param_not_number", `«${param.label}» tiene que ser un número.`, { param: param.label });
239					break;
240				}
241				if (param.min !== undefined && value < param.min) {
242					fail("out_of_range", "param_min_value", `«${param.label}» no puede bajar de ${param.min}.`, {
243						param: param.label,
244						min: param.min
245					});
246				}
247				if (param.max !== undefined && value > param.max) {
248					fail("out_of_range", "param_max_value", `«${param.label}» no puede pasar de ${param.max}.`, {
249						param: param.label,
250						max: param.max
251					});
252				}
253				break;
254			}
255	
256			case "boolean": {
257				if (typeof value !== "boolean") {
258					fail("bad_format", "param_not_boolean", `«${param.label}» tiene que ser sí o no.`, { param: param.label });
259				}
260				break;
261			}
262	
263			case "channel":
264			case "role":
265			case "user": {
266				if (typeof value !== "string" || !SNOWFLAKE.test(value)) {
267					fail(
268						"bad_format",
269						"param_bad_snowflake",
270						`«${param.label}» no es un identificador de Discord válido.`,
271						{ param: param.label }
272					);
273				}
274				break;
275			}
276	
277			case "channel_list":
278			case "category_list":
279			case "role_list": {
280				if (!Array.isArray(value)) {
281					fail("bad_format", "param_not_list", `«${param.label}» tiene que ser una lista.`, { param: param.label });
282					break;
283				}
284				if (value.some((v) => typeof v !== "string" || !SNOWFLAKE.test(v))) {
285					fail(
286						"bad_format",
287						"param_bad_snowflake_list",
288						`«${param.label}» contiene un identificador de Discord que no es válido.`,
289						{ param: param.label }
290					);
291				}
292				break;
293			}
294	
295			case "select": {
296				const allowed = new Set((param.options ?? []).map((o) => o.value));
297				if (param.multiple && !Array.isArray(value)) {
298					fail("bad_format", "param_not_list", `«${param.label}» tiene que ser una lista.`, { param: param.label });
299					break;
300				}
301				const values = param.multiple ? (value as unknown[]) : [value];
302				for (const v of values) {
303					if (typeof v !== "string" || !allowed.has(v)) {
304						fail(
305							"bad_format",
306							"param_not_in_options",
307							`«${param.label}» tiene un valor que no está entre las opciones.`,
308							{ param: param.label }
309						);
310						break;
311					}
312				}
313				break;
314			}
315	
316			case "image_canvas": {
317				if (typeof value !== "object" || Array.isArray(value)) {
318					fail("bad_format", "param_not_canvas", `«${param.label}» tiene que ser un lienzo.`, { param: param.label });
319					break;
320				}
321				const canvas = value as Record<string, unknown>;
322				if (typeof canvas.width !== "number" || typeof canvas.height !== "number") {
323					fail("bad_format", "param_canvas_size", `«${param.label}» necesita un ancho y un alto numéricos.`, {
324						param: param.label
325					});
326				}
327				if (!Array.isArray(canvas.elements)) {
328					fail("bad_format", "param_canvas_elements", `«${param.label}» necesita una lista de elementos.`, {
329						param: param.label
330					});
331				}
332				break;
333			}
334	
335			case "image": {
336				if (typeof value !== "string") {
337					fail("bad_format", "param_not_image", `«${param.label}» tiene que ser una imagen.`, { param: param.label });
338				}
339				break;
340			}
341		}
342	
343		return issues;
344	}
345	
346	/**
347	 * ¿Se pinta este param, dado el valor actual —o el `default` del param
348	 * hermano si `key` todavía no está en `values`— de su `visibleWhen`? Mismo
349	 * criterio de fallback que usa `ParamFields` en la dashboard para decidir
350	 * qué control mostrar: si divergieran, un param oculto en la dashboard
351	 * podría seguir bloqueando el guardado aquí (o al revés).
352	 */
353	export function isParamVisible(param: ModerationFlowParam, values: Record<string, unknown>, defs: ModerationFlowParam[]): boolean {
354		if (!param.visibleWhen) return true;
355		const { key, equals } = param.visibleWhen;
356		const raw = values[key];
357		const effective = raw !== undefined ? raw : defs.find((d) => d.key === key)?.default;
358		return typeof effective === "string" && equals.includes(effective);
359	}
360	
361	/** Valida el objeto `params` de un bloque contra la especificación del catálogo. */
362	export function validateFlowParams(
363		params: Record<string, unknown> | undefined,
364		defs: ModerationFlowParam[],
365		path: string
366	): ModerationFlowIssue[] {
367		const values = params ?? {};
368		// Un param oculto por `visibleWhen` no puede generar un issue de «falta
369		// rellenar»: se salta ENTERO, `required` y forma incluidos.
370		return defs.flatMap((param) => (isParamVisible(param, values, defs) ? checkOne(param, values[param.key], path) : []));
371	}
372	
373	// ─── Flujo completo ─────────────────────────────────────────────────────────
374	
375	/**
376	 * Condiciones/pasos cuyo `type` no está en el catálogo no tienen código propio
377	 * en el contrato (§2.6 no lista `unknown_condition`/`unknown_action`): un
378	 * `type` así sólo puede llegar de un documento tocado a mano, porque el
379	 * `FlowBlockPicker` de la dashboard sólo ofrece claves del catálogo. Se modela
380	 * como `missing_context` — no podemos saber qué necesita un bloque que no
381	 * reconocemos, así que se trata como si le faltase todo.
382	 */
383	function validateConditionList(
384		conditions: ModerationFlowConditionInstance[] | undefined,
385		provided: Set<ModerationFlowContextKey>,
386		pathPrefix: string
387	): ModerationFlowIssue[] {
388		const issues: ModerationFlowIssue[] = [];
389		conditions?.forEach((condition, index) => {
390			const at = `${pathPrefix}[${index}]`;
391			const def = (MODERATION_FLOW_CONDITIONS as Record<string, ModerationFlowConditionDef>)[condition.type];
392			if (!def) {
393				issues.push({
394					path: `${at}.type`,
395					code: "missing_context",
396					messageKey: "condition_unknown",
397					message: "Esa condición no existe en el catálogo."
398				});
399				return;
400			}
401			const missing = def.requires.filter((k) => !provided.has(k));
402			if (missing.length > 0) {
403				issues.push({
404					path: `${at}.type`,
405					code: "missing_context",
406					messageKey: "block_missing_context",
407					message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`,
408					values: { block: def.label, missing: missing.join(", ") }
409				});
410			}
411			issues.push(...validateFlowParams(condition.params, def.params, `${at}.params`));
412		});
413		return issues;
414	}
415	
416	/** Valida una lista de pasos contra el contexto del disparador. Mismo criterio que las condiciones. */
417	function validateStepList(
418		steps: ModerationFlowStepInstance[] | undefined,
419		provided: Set<ModerationFlowContextKey>,
420		pathPrefix: string
421	): ModerationFlowIssue[] {
422		const issues: ModerationFlowIssue[] = [];
423		steps?.forEach((step, index) => {
424			const at = `${pathPrefix}[${index}]`;
425			const def = (MODERATION_FLOW_ACTIONS as Record<string, ModerationFlowActionDef>)[step.type];
426			if (!def) {
427				issues.push({
428					path: `${at}.type`,
429					code: "missing_context",
430					messageKey: "step_unknown",
431					message: "Ese paso no existe en el catálogo."
432				});
433				return;
434			}
435			const missing = def.requires.filter((k) => !provided.has(k));
436			if (missing.length > 0) {
437				issues.push({
438					path: `${at}.type`,
439					code: "missing_context",
440					messageKey: "block_missing_context",
441					message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`,
442					values: { block: def.label, missing: missing.join(", ") }
443				});
444			}
445			issues.push(...validateFlowParams(step.params, def.params, `${at}.params`));
446		});
447		return issues;
448	}
449	
450	/**
451	 * `set_variable` con `name` duplicado EN EL MISMO CAMINO. `setup` se ejecuta
452	 * siempre antes de la bifurcación, así que sus variables cuentan para TODOS
453	 * los caminos; pero `steps` de la raíz y `steps` de cada rama son alternativas
454	 * mutuamente excluyentes entre sí (`chooseBranch` sólo ejecuta una), así que
455	 * repetir un nombre en dos ramas distintas NO es un problema — nunca coexisten
456	 * en una misma ejecución.
457	 */
458	function checkDuplicateVariableNames(
459		setupSteps: ModerationFlowStepInstance[],
460		pathSteps: ModerationFlowStepInstance[],
461		pathPrefix: string
462	): ModerationFlowIssue[] {
463		const issues: ModerationFlowIssue[] = [];
464		const seen = new Set<string>();
465	
466		const scan = (steps: ModerationFlowStepInstance[], prefix: string) => {
467			steps.forEach((step, index) => {
468				if (step.type !== "set_variable") return;
469				const name = step.params?.name;
470				if (typeof name !== "string" || name === "") return;
471				if (seen.has(name)) {
472					issues.push({
473						path: `${prefix}[${index}].params.name`,
474						code: "duplicate_variable",
475						messageKey: "duplicate_variable",
476						message: `La variable «${name}» ya se guardó antes en este mismo camino.`,
477						values: { name }
478					});
479				} else {
480					seen.add(name);
481				}
482			});
483		};
484	
485		scan(setupSteps, "setup");
486		scan(pathSteps, pathPrefix);
487		return issues;
488	}
489	
490	/**
491	 * Valida un flujo entero. Lista vacía = se puede guardar/publicar.
492	 *
493	 * El orden importa: si el disparador no se reconoce se para ahí, porque sin
494	 * saber qué contexto aporta, todos los errores de contexto de abajo serían
495	 * ruido derivado del primero.
496	 */
497	export function validateFlow(flow: ModerationFlowInstance): ModerationFlowIssue[] {
498		const issues: ModerationFlowIssue[] = [];
499	
500		const triggerType = flow.trigger?.type;
501		if (!triggerType || !isModerationFlowTriggerType(triggerType)) {
502			issues.push({
503				path: "trigger.type",
504				code: "unknown_trigger",
505				messageKey: "trigger_unknown",
506				message: "Ese disparador no existe. Puede que se haya retirado del catálogo."
507			});
508			return issues;
509		}
510	
511		const trigger = MODERATION_FLOW_TRIGGERS[triggerType];
512		const provided = new Set<ModerationFlowContextKey>(trigger.provides);
513		const setup = flow.setup ?? [];
514	
515		issues.push(...validateFlowParams(flow.trigger.params, trigger.params, "trigger.params"));
516		issues.push(...validateStepList(setup, provided, "setup"));
517		issues.push(...validateConditionList(flow.conditions, provided, "conditions"));
518		issues.push(...validateStepList(flow.steps, provided, "steps"));
519		issues.push(...checkDuplicateVariableNames(setup, flow.steps ?? [], "steps"));
520	
521		if (!flow.steps || flow.steps.length === 0) {
522			issues.push({
523				path: "steps",
524				code: "empty_branch",
525				messageKey: "empty_root_steps",
526				message: "Este camino no hace nada: añade un paso."
527			});
528		}
529	
530		// ── Ramas alternativas ────────────────────────────────────────────────────
531		const branches = flow.branches ?? [];
532		branches.forEach((branch, index) => {
533			const at = `branches[${index}]`;
534	
535			issues.push(...validateConditionList(branch.conditions, provided, `${at}.conditions`));
536			issues.push(...validateStepList(branch.steps, provided, `${at}.steps`));
537			issues.push(...checkDuplicateVariableNames(setup, branch.steps ?? [], `${at}.steps`));
538	
539			if (!branch.steps || branch.steps.length === 0) {
540				issues.push({
541					path: `${at}.steps`,
542					code: "empty_branch",
543					messageKey: "empty_branch_steps",
544					message: "Esta rama no hace nada: añade un paso o quítala."
545				});
546			}
547	
548			// Una rama SIN condiciones es el «si no» final: pasa siempre, así que todo
549			// lo que venga detrás no se ejecutará jamás.
550			const isElse = (branch.conditions?.length ?? 0) === 0;
551			if (isElse && index !== branches.length - 1) {
552				issues.push({
553					path: `${at}.conditions`,
554					code: "unreachable_branch",
555					messageKey: "unreachable_branch",
556					message: "«Si no» tiene que ir el último: las ramas siguientes nunca se ejecutarían."
557				});
558			}
559		});
560	
561		const hasAnySteps = (flow.steps?.length ?? 0) > 0 || branches.some((b) => (b.steps?.length ?? 0) > 0);
562		if (!hasAnySteps) {
563			issues.push({
564				path: "steps",
565				code: "empty_flow",
566				messageKey: "empty_flow",
567				message: "El flujo no hace nada en ningún camino: añade al menos un paso."
568			});
569		}
570	
571		return issues;
572	}
573	
574	// ─── Defaults ─────────────────────────────────────────────────────────────────
575	
576	/** Scope de fábrica de un flujo nuevo: sin filtrar nada, con los dos cortafuegos anti-bucle activados. */
577	export function defaultFlowScope(): ModerationFlowScopeInstance {
578		return {
579			channels: { mode: "all_except", ids: [] },
580			categories: { mode: "all_except", ids: [] },
581			roles: { mode: "all_except", ids: [] },
582			ignore_bots: true,
583			ignore_admins: true,
584			cooldown_seconds: 0,
585			rate_limit_per_minute: 0
586		};
587	}
588	
589	/**
590	 * Flujo nuevo con el disparador ya elegido. Nace DESACTIVADO (`enabled: false`)
591	 * a propósito, igual que una automatización nace en `draft`: hasta que quien lo
592	 * monta no lo activa explícitamente, no debe correr contra Discord con
593	 * condiciones y pasos todavía vacíos.
594	 */
595	export function newFlow(triggerType: string): ModerationFlowInstance {
596		const now = new Date().toISOString();
597		const trigger = isModerationFlowTriggerType(triggerType) ? MODERATION_FLOW_TRIGGERS[triggerType] : undefined;
598	
599		return {
600			id: crypto.randomUUID(),
601			name: "Nuevo flujo",
602			enabled: false,
603			trigger: { type: triggerType, params: trigger ? buildDefaultParams(trigger.params) : {} },
604			scope: defaultFlowScope(),
605			setup: [],
606			condition_mode: "and",
607			conditions: [],
608			steps: [],
609			branches: [],
610			debug_until: null,
611			created_at: now,
612			updated_at: now
613		};
614	}
