/**
 * ESPEJO de `libraries/library-shared/src/moderation-flows/validate.ts`.
 *
 * `dashboard/` NO es miembro del workspace pnpm: instala `@kena/shared` del
 * registro PRIVADO (un tarball versionado), no la copia local del monorepo.
 * Republicar ese paquete para que incluya este catálogo es un despliegue en DOS
 * pasos (primero `@kena/shared`, luego la dashboard), así que este fichero es
 * una copia MANTENIDA A MANO del canónico — no se puede hacer todavía
 * `export * from "@kena/shared/moderation-flows"`.
 *
 * `catalog-mirror.test.ts` compara este fichero con el canónico BYTE A BYTE
 * (salvo esta cabecera y la línea de import de `@kena/shared/automation`) y
 * FALLA si divergen. Si tocas uno, toca el otro.
 */

import { MODERATION_FLOW_ACTIONS } from "./actions.js";
import { MODERATION_FLOW_CONDITIONS } from "./conditions.js";
import { MODERATION_FLOW_TRIGGERS } from "./triggers.js";
import {
	MODERATION_FLOW_ACTION_KEYS,
	MODERATION_FLOW_CONDITION_KEYS,
	MODERATION_FLOW_TRIGGER_KEYS,
	type ModerationFlowActionDef,
	type ModerationFlowActionType,
	type ModerationFlowConditionDef,
	type ModerationFlowConditionInstance,
	type ModerationFlowConditionType,
	type ModerationFlowContextKey,
	type ModerationFlowInstance,
	type ModerationFlowParam,
	type ModerationFlowScopeInstance,
	type ModerationFlowStepInstance,
	type ModerationFlowTriggerType
} from "./types.js";

/**
 * Validación de flujos de moderación contra el catálogo. La usan las DOS
 * puntas: la dashboard para no dejar publicar un flujo roto, y el módulo para
 * no ejecutar uno que llegue roto de todos modos (un documento viejo, una
 * edición a mano en Mongo, un catálogo recortado).
 *
 * Devuelve una lista de problemas en vez de lanzar: la dashboard los pinta
 * todos a la vez junto a su bloque, que es lo que espera quien está montando
 * el flujo.
 */

export type ModerationFlowIssueCode =
	| "unknown_trigger"
	| "missing_context"
	| "missing_param"
	| "bad_regex"
	| "out_of_range"
	| "bad_format"
	| "unreachable_branch"
	| "empty_branch"
	| "duplicate_variable"
	| "empty_flow";

export interface ModerationFlowIssue {
	/** Ruta del campo, tal cual la usa la dashboard para anclar el error. */
	path: string;
	code: ModerationFlowIssueCode;
	/**
	 * Identificador estable y específico de ESTE mensaje concreto — a
	 * diferencia de `code`, que agrupa varios mensajes distintos bajo el mismo
	 * contrato con el motor (p. ej. `bad_format` cubre «tiene que ser texto»,
	 * «tiene que ser un número», «no tiene el formato correcto»… con textos y
	 * piezas a interpolar distintos). La dashboard lo usa para traducir vía
	 * `dashboard.guild.moderation.flows.issue.<messageKey>`
	 * (`flowIssueMessage` en `catalog-i18n.ts`).
	 */
	messageKey: string;
	/**
	 * Piezas para interpolar en la traducción de `messageKey` (el nombre del
	 * param, el mínimo/máximo exigido…). Ausente cuando el mensaje no
	 * interpola nada.
	 */
	values?: Record<string, string | number>;
	/** Mensaje en castellano, listo para enseñar. */
	message: string;
}

const SNOWFLAKE = /^\d{17,20}$/;

// ─── Guardas de tipo ──────────────────────────────────────────────────────────

export const isModerationFlowTriggerType = (value: string): value is ModerationFlowTriggerType =>
	(MODERATION_FLOW_TRIGGER_KEYS as readonly string[]).includes(value);

export const isModerationFlowConditionType = (value: string): value is ModerationFlowConditionType =>
	(MODERATION_FLOW_CONDITION_KEYS as readonly string[]).includes(value);

export const isModerationFlowActionType = (value: string): value is ModerationFlowActionType =>
	(MODERATION_FLOW_ACTION_KEYS as readonly string[]).includes(value);

// ─── Compatibilidad disparador ↔ bloque ───────────────────────────────────────

/**
 * Condiciones que se pueden usar con este disparador: las que no piden nada
 * que el disparador no traiga. `triggerType` va sin tipar porque quien llama
 * normalmente tiene un `string` sin validar (el `type` crudo del documento).
 */
export function getAvailableConditions(triggerType: string): ModerationFlowConditionDef[] {
	if (!isModerationFlowTriggerType(triggerType)) return [];
	const provided = new Set<ModerationFlowContextKey>(MODERATION_FLOW_TRIGGERS[triggerType].provides);
	return Object.values(MODERATION_FLOW_CONDITIONS).filter((c) => c.requires.every((k) => provided.has(k)));
}

/** Pasos que se pueden usar con este disparador. Mismo criterio. */
export function getAvailableActions(triggerType: string): ModerationFlowActionDef[] {
	if (!isModerationFlowTriggerType(triggerType)) return [];
	const provided = new Set<ModerationFlowContextKey>(MODERATION_FLOW_TRIGGERS[triggerType].provides);
	return Object.values(MODERATION_FLOW_ACTIONS).filter((a) => a.requires.every((k) => provided.has(k)));
}

// ─── Parámetros ───────────────────────────────────────────────────────────────

/** Objeto de parámetros inicial de un bloque recién añadido, con sus defaults. */
export function buildDefaultParams(params: ModerationFlowParam[]): Record<string, unknown> {
	const out: Record<string, unknown> = {};
	for (const param of params) {
		if (param.default !== undefined) {
			out[param.key] = param.default;
			continue;
		}
		// Sin default declarado. Los campos de lista necesitan un array desde el
		// principio para que el control sepa qué renderizar; el resto se deja
		// AUSENTE para que `missing_param` lo cace si hacía falta.
		if (param.type === "text_list" || param.type.endsWith("_list") || (param.type === "select" && param.multiple)) {
			out[param.key] = [];
		} else if (param.type === "boolean") {
			out[param.key] = false;
		}
	}
	return out;
}

/** ¿Cuenta como «sin rellenar»? `false` y `0` NO — son valores legítimos. */
const isEmpty = (value: unknown): boolean =>
	value === undefined || value === null || value === "" || (Array.isArray(value) && value.length === 0);

function checkOne(param: ModerationFlowParam, value: unknown, path: string): ModerationFlowIssue[] {
	const issues: ModerationFlowIssue[] = [];
	const at = `${path}.${param.key}`;
	// `paramKey` se inyecta AQUÍ, en el único punto por el que pasan todos los
	// fallos de un param, en vez de repetirlo en los quince `fail(...)` de
	// abajo. Lo necesita la dashboard: `values.param` es el rótulo del
	// catálogo, o sea CASTELLANO, y sin la clave no hay forma de volver a
	// traducirlo — el mensaje saldría «"Motivo" is required.» en inglés. El
	// motor del bot ignora `values` y sigue registrando `message` tal cual.
	const fail = (
		code: ModerationFlowIssueCode,
		messageKey: string,
		message: string,
		values?: Record<string, string | number>
	) =>
		issues.push({
			path: at,
			code,
			messageKey,
			message,
			values: values && "param" in values ? { ...values, paramKey: param.key } : values
		});

	if (isEmpty(value)) {
		if (param.required) {
			fail("missing_param", "param_required", `«${param.label}» es obligatorio.`, { param: param.label });
		}
		return issues;
	}

	switch (param.type) {
		case "text_list": {
			if (!Array.isArray(value) || value.some((v) => typeof v !== "string")) {
				fail("bad_format", "param_not_text_list", `«${param.label}» tiene que ser una lista de textos.`, {
					param: param.label
				});
				break;
			}
			if (param.min !== undefined && value.length < param.min) {
				fail("out_of_range", "param_min_items", `«${param.label}» necesita al menos ${param.min} valores.`, {
					param: param.label,
					min: param.min
				});
			}
			if (param.max !== undefined && value.length > param.max) {
				fail("out_of_range", "param_max_items", `«${param.label}» admite como mucho ${param.max} valores.`, {
					param: param.label,
					max: param.max
				});
			}
			break;
		}

		case "text":
		case "long_text":
		case "emoji":
		case "counter":
		case "automation":
		case "regex":
		case "color": {
			if (typeof value !== "string") {
				fail("bad_format", "param_not_text", `«${param.label}» tiene que ser texto.`, { param: param.label });
				break;
			}
			if (param.min !== undefined && value.length < param.min) {
				fail("out_of_range", "param_min_length", `«${param.label}» necesita al menos ${param.min} caracteres.`, {
					param: param.label,
					min: param.min
				});
			}
			if (param.max !== undefined && value.length > param.max) {
				fail("out_of_range", "param_max_length", `«${param.label}» admite como mucho ${param.max} caracteres.`, {
					param: param.label,
					max: param.max
				});
			}
			if (param.pattern && !new RegExp(param.pattern).test(value)) {
				fail("bad_format", "param_bad_pattern", `«${param.label}» no tiene el formato correcto.`, {
					param: param.label
				});
			}
			if (param.type === "regex") {
				try {
					new RegExp(value, "u");
				} catch {
					fail("bad_regex", "param_bad_regex", `«${param.label}» no es una expresión regular válida.`, {
						param: param.label
					});
				}
			}
			break;
		}

		case "number":
		case "duration": {
			if (typeof value !== "number" || !Number.isFinite(value)) {
				fail("bad_format", "param_not_number", `«${param.label}» tiene que ser un número.`, { param: param.label });
				break;
			}
			if (param.min !== undefined && value < param.min) {
				fail("out_of_range", "param_min_value", `«${param.label}» no puede bajar de ${param.min}.`, {
					param: param.label,
					min: param.min
				});
			}
			if (param.max !== undefined && value > param.max) {
				fail("out_of_range", "param_max_value", `«${param.label}» no puede pasar de ${param.max}.`, {
					param: param.label,
					max: param.max
				});
			}
			break;
		}

		case "boolean": {
			if (typeof value !== "boolean") {
				fail("bad_format", "param_not_boolean", `«${param.label}» tiene que ser sí o no.`, { param: param.label });
			}
			break;
		}

		case "channel":
		case "role":
		case "user": {
			if (typeof value !== "string" || !SNOWFLAKE.test(value)) {
				fail(
					"bad_format",
					"param_bad_snowflake",
					`«${param.label}» no es un identificador de Discord válido.`,
					{ param: param.label }
				);
			}
			break;
		}

		case "channel_list":
		case "category_list":
		case "role_list": {
			if (!Array.isArray(value)) {
				fail("bad_format", "param_not_list", `«${param.label}» tiene que ser una lista.`, { param: param.label });
				break;
			}
			if (value.some((v) => typeof v !== "string" || !SNOWFLAKE.test(v))) {
				fail(
					"bad_format",
					"param_bad_snowflake_list",
					`«${param.label}» contiene un identificador de Discord que no es válido.`,
					{ param: param.label }
				);
			}
			break;
		}

		case "select": {
			const allowed = new Set((param.options ?? []).map((o) => o.value));
			if (param.multiple && !Array.isArray(value)) {
				fail("bad_format", "param_not_list", `«${param.label}» tiene que ser una lista.`, { param: param.label });
				break;
			}
			const values = param.multiple ? (value as unknown[]) : [value];
			for (const v of values) {
				if (typeof v !== "string" || !allowed.has(v)) {
					fail(
						"bad_format",
						"param_not_in_options",
						`«${param.label}» tiene un valor que no está entre las opciones.`,
						{ param: param.label }
					);
					break;
				}
			}
			break;
		}

		case "image_canvas": {
			if (typeof value !== "object" || Array.isArray(value)) {
				fail("bad_format", "param_not_canvas", `«${param.label}» tiene que ser un lienzo.`, { param: param.label });
				break;
			}
			const canvas = value as Record<string, unknown>;
			if (typeof canvas.width !== "number" || typeof canvas.height !== "number") {
				fail("bad_format", "param_canvas_size", `«${param.label}» necesita un ancho y un alto numéricos.`, {
					param: param.label
				});
			}
			if (!Array.isArray(canvas.elements)) {
				fail("bad_format", "param_canvas_elements", `«${param.label}» necesita una lista de elementos.`, {
					param: param.label
				});
			}
			break;
		}

		case "image": {
			if (typeof value !== "string") {
				fail("bad_format", "param_not_image", `«${param.label}» tiene que ser una imagen.`, { param: param.label });
			}
			break;
		}
	}

	return issues;
}

/**
 * ¿Se pinta este param, dado el valor actual —o el `default` del param
 * hermano si `key` todavía no está en `values`— de su `visibleWhen`? Mismo
 * criterio de fallback que usa `ParamFields` en la dashboard para decidir
 * qué control mostrar: si divergieran, un param oculto en la dashboard
 * podría seguir bloqueando el guardado aquí (o al revés).
 */
export function isParamVisible(param: ModerationFlowParam, values: Record<string, unknown>, defs: ModerationFlowParam[]): boolean {
	if (!param.visibleWhen) return true;
	const { key, equals } = param.visibleWhen;
	const raw = values[key];
	const effective = raw !== undefined ? raw : defs.find((d) => d.key === key)?.default;
	return typeof effective === "string" && equals.includes(effective);
}

/** Valida el objeto `params` de un bloque contra la especificación del catálogo. */
export function validateFlowParams(
	params: Record<string, unknown> | undefined,
	defs: ModerationFlowParam[],
	path: string
): ModerationFlowIssue[] {
	const values = params ?? {};
	// Un param oculto por `visibleWhen` no puede generar un issue de «falta
	// rellenar»: se salta ENTERO, `required` y forma incluidos.
	return defs.flatMap((param) => (isParamVisible(param, values, defs) ? checkOne(param, values[param.key], path) : []));
}

// ─── Flujo completo ─────────────────────────────────────────────────────────

/**
 * Condiciones/pasos cuyo `type` no está en el catálogo no tienen código propio
 * en el contrato (§2.6 no lista `unknown_condition`/`unknown_action`): un
 * `type` así sólo puede llegar de un documento tocado a mano, porque el
 * `FlowBlockPicker` de la dashboard sólo ofrece claves del catálogo. Se modela
 * como `missing_context` — no podemos saber qué necesita un bloque que no
 * reconocemos, así que se trata como si le faltase todo.
 */
function validateConditionList(
	conditions: ModerationFlowConditionInstance[] | undefined,
	provided: Set<ModerationFlowContextKey>,
	pathPrefix: string
): ModerationFlowIssue[] {
	const issues: ModerationFlowIssue[] = [];
	conditions?.forEach((condition, index) => {
		const at = `${pathPrefix}[${index}]`;
		const def = (MODERATION_FLOW_CONDITIONS as Record<string, ModerationFlowConditionDef>)[condition.type];
		if (!def) {
			issues.push({
				path: `${at}.type`,
				code: "missing_context",
				messageKey: "condition_unknown",
				message: "Esa condición no existe en el catálogo."
			});
			return;
		}
		const missing = def.requires.filter((k) => !provided.has(k));
		if (missing.length > 0) {
			issues.push({
				path: `${at}.type`,
				code: "missing_context",
				messageKey: "block_missing_context",
				message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`,
				values: { block: def.label, missing: missing.join(", ") }
			});
		}
		issues.push(...validateFlowParams(condition.params, def.params, `${at}.params`));
	});
	return issues;
}

/** Valida una lista de pasos contra el contexto del disparador. Mismo criterio que las condiciones. */
function validateStepList(
	steps: ModerationFlowStepInstance[] | undefined,
	provided: Set<ModerationFlowContextKey>,
	pathPrefix: string
): ModerationFlowIssue[] {
	const issues: ModerationFlowIssue[] = [];
	steps?.forEach((step, index) => {
		const at = `${pathPrefix}[${index}]`;
		const def = (MODERATION_FLOW_ACTIONS as Record<string, ModerationFlowActionDef>)[step.type];
		if (!def) {
			issues.push({
				path: `${at}.type`,
				code: "missing_context",
				messageKey: "step_unknown",
				message: "Ese paso no existe en el catálogo."
			});
			return;
		}
		const missing = def.requires.filter((k) => !provided.has(k));
		if (missing.length > 0) {
			issues.push({
				path: `${at}.type`,
				code: "missing_context",
				messageKey: "block_missing_context",
				message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`,
				values: { block: def.label, missing: missing.join(", ") }
			});
		}
		issues.push(...validateFlowParams(step.params, def.params, `${at}.params`));
	});
	return issues;
}

/**
 * `set_variable` con `name` duplicado EN EL MISMO CAMINO. `setup` se ejecuta
 * siempre antes de la bifurcación, así que sus variables cuentan para TODOS
 * los caminos; pero `steps` de la raíz y `steps` de cada rama son alternativas
 * mutuamente excluyentes entre sí (`chooseBranch` sólo ejecuta una), así que
 * repetir un nombre en dos ramas distintas NO es un problema — nunca coexisten
 * en una misma ejecución.
 */
function checkDuplicateVariableNames(
	setupSteps: ModerationFlowStepInstance[],
	pathSteps: ModerationFlowStepInstance[],
	pathPrefix: string
): ModerationFlowIssue[] {
	const issues: ModerationFlowIssue[] = [];
	const seen = new Set<string>();

	const scan = (steps: ModerationFlowStepInstance[], prefix: string) => {
		steps.forEach((step, index) => {
			if (step.type !== "set_variable") return;
			const name = step.params?.name;
			if (typeof name !== "string" || name === "") return;
			if (seen.has(name)) {
				issues.push({
					path: `${prefix}[${index}].params.name`,
					code: "duplicate_variable",
					messageKey: "duplicate_variable",
					message: `La variable «${name}» ya se guardó antes en este mismo camino.`,
					values: { name }
				});
			} else {
				seen.add(name);
			}
		});
	};

	scan(setupSteps, "setup");
	scan(pathSteps, pathPrefix);
	return issues;
}

/**
 * Valida un flujo entero. Lista vacía = se puede guardar/publicar.
 *
 * El orden importa: si el disparador no se reconoce se para ahí, porque sin
 * saber qué contexto aporta, todos los errores de contexto de abajo serían
 * ruido derivado del primero.
 */
export function validateFlow(flow: ModerationFlowInstance): ModerationFlowIssue[] {
	const issues: ModerationFlowIssue[] = [];

	const triggerType = flow.trigger?.type;
	if (!triggerType || !isModerationFlowTriggerType(triggerType)) {
		issues.push({
			path: "trigger.type",
			code: "unknown_trigger",
			messageKey: "trigger_unknown",
			message: "Ese disparador no existe. Puede que se haya retirado del catálogo."
		});
		return issues;
	}

	const trigger = MODERATION_FLOW_TRIGGERS[triggerType];
	const provided = new Set<ModerationFlowContextKey>(trigger.provides);
	const setup = flow.setup ?? [];

	issues.push(...validateFlowParams(flow.trigger.params, trigger.params, "trigger.params"));
	issues.push(...validateStepList(setup, provided, "setup"));
	issues.push(...validateConditionList(flow.conditions, provided, "conditions"));
	issues.push(...validateStepList(flow.steps, provided, "steps"));
	issues.push(...checkDuplicateVariableNames(setup, flow.steps ?? [], "steps"));

	if (!flow.steps || flow.steps.length === 0) {
		issues.push({
			path: "steps",
			code: "empty_branch",
			messageKey: "empty_root_steps",
			message: "Este camino no hace nada: añade un paso."
		});
	}

	// ── Ramas alternativas ────────────────────────────────────────────────────
	const branches = flow.branches ?? [];
	branches.forEach((branch, index) => {
		const at = `branches[${index}]`;

		issues.push(...validateConditionList(branch.conditions, provided, `${at}.conditions`));
		issues.push(...validateStepList(branch.steps, provided, `${at}.steps`));
		issues.push(...checkDuplicateVariableNames(setup, branch.steps ?? [], `${at}.steps`));

		if (!branch.steps || branch.steps.length === 0) {
			issues.push({
				path: `${at}.steps`,
				code: "empty_branch",
				messageKey: "empty_branch_steps",
				message: "Esta rama no hace nada: añade un paso o quítala."
			});
		}

		// Una rama SIN condiciones es el «si no» final: pasa siempre, así que todo
		// lo que venga detrás no se ejecutará jamás.
		const isElse = (branch.conditions?.length ?? 0) === 0;
		if (isElse && index !== branches.length - 1) {
			issues.push({
				path: `${at}.conditions`,
				code: "unreachable_branch",
				messageKey: "unreachable_branch",
				message: "«Si no» tiene que ir el último: las ramas siguientes nunca se ejecutarían."
			});
		}
	});

	const hasAnySteps = (flow.steps?.length ?? 0) > 0 || branches.some((b) => (b.steps?.length ?? 0) > 0);
	if (!hasAnySteps) {
		issues.push({
			path: "steps",
			code: "empty_flow",
			messageKey: "empty_flow",
			message: "El flujo no hace nada en ningún camino: añade al menos un paso."
		});
	}

	return issues;
}

// ─── Defaults ─────────────────────────────────────────────────────────────────

/** Scope de fábrica de un flujo nuevo: sin filtrar nada, con los dos cortafuegos anti-bucle activados. */
export function defaultFlowScope(): ModerationFlowScopeInstance {
	return {
		channels: { mode: "all_except", ids: [] },
		categories: { mode: "all_except", ids: [] },
		roles: { mode: "all_except", ids: [] },
		ignore_bots: true,
		ignore_admins: true,
		cooldown_seconds: 0,
		rate_limit_per_minute: 0
	};
}

/**
 * Flujo nuevo con el disparador ya elegido. Nace DESACTIVADO (`enabled: false`)
 * a propósito, igual que una automatización nace en `draft`: hasta que quien lo
 * monta no lo activa explícitamente, no debe correr contra Discord con
 * condiciones y pasos todavía vacíos.
 */
export function newFlow(triggerType: string): ModerationFlowInstance {
	const now = new Date().toISOString();
	const trigger = isModerationFlowTriggerType(triggerType) ? MODERATION_FLOW_TRIGGERS[triggerType] : undefined;

	return {
		id: crypto.randomUUID(),
		name: "Nuevo flujo",
		enabled: false,
		trigger: { type: triggerType, params: trigger ? buildDefaultParams(trigger.params) : {} },
		scope: defaultFlowScope(),
		setup: [],
		condition_mode: "and",
		conditions: [],
		steps: [],
		branches: [],
		debug_until: null,
		created_at: now,
		updated_at: now
	};
}

