package handlers

import "encoding/json"

// patchMap re-decodes an already-validated module PATCH body as a raw
// `map[string]any` so key PRESENCE survives the trip to the repository merge.
// The strict struct decode that precedes it enforces the schema (unknown keys
// → 400); this second decode is what lets explicit `false`/`0`/`""`/`null`
// leaves reach `mongo.MergeDeepJSON` and be APPLIED — exact parity with the
// Node `mergeDeep`, which only skips `undefined`.
//
// A literal `null` body normalises to an empty map (no-op merge, like `{}`).
func patchMap(body []byte) (map[string]any, error) {
	var m map[string]any
	if err := json.Unmarshal(body, &m); err != nil {
		return nil, err
	}
	if m == nil {
		m = map[string]any{}
	}
	return m, nil
}

