// modmailTicketTypeBody arma un `ticket_types` con un solo campo por tipo — el
// decodificador estricto no exige el resto de claves del objeto anidado, así que
// basta el id para ejercitar la validación de ids.
func modmailTicketTypeBody(ids ...string) map[string]any {
	types := make([]map[string]any, 0, len(ids))
	for _, id := range ids {
		types = append(types, map[string]any{"id": id, "label": "T"})
	}
	return map[string]any{"ticket_types": types}
}

// TestModmailPatch_ReservedTicketTypeID_400 🛡️ — un tipo REAL no puede robar
// ninguno de los dos ids reservados. El dashboard ya lo valida con zod, pero eso
// es el cliente: con un token se llega aquí directamente, y un tipo que se quede
// con "none" hace que TODO el histórico sin clasificar empiece a resolver a él.
func TestModmailPatch_ReservedTicketTypeID_400(t *testing.T) {
	for _, reserved := range []string{
		dbmodmailticket.NoTicketTypeID,
		dbmodmailticket.ContactTicketTypeID,
	} {
		t.Run(reserved, func(t *testing.T) {
			repo := &mocks.FakeModuleModmailRepo{}
			app := newModmailMockApp(repo)
			status, hdr, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/modmail/",
				"Bearer "+testSecret, modmailTicketTypeBody("uuid-ok", reserved))
			if status != 400 {
				t.Fatalf("status = %d, want 400\nbody: %s", status, body)
			}
			if got := hdr.Get(handlers.HeaderErrorType); got != "ZOD" {
				t.Fatalf("x-error-type = %q, want ZOD\nbody: %s", got, body)
			}
			if !bytes.Contains(body, []byte("ticket_types.1.id")) {
				t.Fatalf("el error debe señalar la fila concreta: %s", body)
			}
			if len(repo.UpdateCalls) != 0 {
				t.Fatalf("UpdateCalls = %d, want 0 (rechazo antes del repo)", len(repo.UpdateCalls))
			}
		})
	}
}

