package handlers_test

import (
	"bytes"
	"encoding/json"
	"errors"
	"testing"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/application/handlers"
	"kena.bot/api-db-go/internal/application/middlewares"
	"kena.bot/api-db-go/internal/application/routers"
	"kena.bot/api-db-go/internal/domain/dbguild"
	"kena.bot/api-db-go/internal/domain/mocks"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
)

// newModerationMockApp mounts the guild-scoped moderation routes behind the auth
// middleware, backed by the supplied fake repo.
func newModerationMockApp(repo mongorepo.ModuleModerationRepo) *fiber.App {
	app := fiber.New(fiber.Config{AppName: "api-db-go-moderation-mock-test"})
	app.Use(middlewares.Recover())
	app.Use(middlewares.Auth(testSecret))
	h := handlers.NewModuleModerationHandler(repo)
	routers.RegisterModuleModeration(app, h)
	return app
}

func moderationSourced(m dbguild.ModuleModeration, source, detail string) *mongorepo.Sourced[dbguild.ModuleModeration] {
	return &mongorepo.Sourced[dbguild.ModuleModeration]{Data: m, Source: source, SourceDetail: detail}
}

// TestModerationGet_Success 🛡️ — a found moderation subdoc returns 200 with the
// full default-filled block and source=db; empty access-list ids serialise `[]`,
// the AutoMod sub-arrays serialise `[]`, and the nullable ids serialise `null`.
func TestModerationGet_Success(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		FindModuleFn: func(string, string, bool) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return moderationSourced(mocks.NewModuleModeration(), "db", "mongo.guild.module_moderation"), nil
		},
	}
	app := newModerationMockApp(repo)
	status, hdr, body := doModuleReq(t, app, "GET", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, nil)
	if status != 200 {
		t.Fatalf("status = %d, want 200\nbody: %s", status, body)
	}
	var env struct {
		Data struct {
			SchemaVersion      int    `json:"schema_version"`
			CommandMode        string `json:"command_mode"`
			TrackNativeActions bool   `json:"track_native_actions"`
			Automod            struct {
				Mentions struct {
					TimeoutMs int `json:"timeout_ms"`
				} `json:"mentions"`
			} `json:"automod"`
		} `json:"data"`
	}
	if err := json.Unmarshal(body, &env); err != nil {
		t.Fatalf("unmarshal: %v\nbody: %s", err, body)
	}
	if env.Data.SchemaVersion != dbguild.SchemaVersionModeration {
		t.Fatalf("schema_version = %d, want %d", env.Data.SchemaVersion, dbguild.SchemaVersionModeration)
	}
	if env.Data.CommandMode != "both" {
		t.Fatalf("command_mode = %q, want both", env.Data.CommandMode)
	}
	if !env.Data.TrackNativeActions {
		t.Fatalf("track_native_actions = false, want true (default)")
	}
	if env.Data.Automod.Mentions.TimeoutMs != 300000 {
		t.Fatalf("automod.mentions.timeout_ms = %d, want 300000 (default)", env.Data.Automod.Mentions.TimeoutMs)
	}
	if got := hdr.Get(handlers.HeaderResultSource); got != "db" {
		t.Fatalf("X-Result-Source = %q, want db", got)
	}
	// Empty collections must serialise as [] / {}, never null; nullable ids as null.
	for _, forbidden := range []string{`"ids":null`, `"exempt_roles":null`, `"commands":null`, `"aliases":null`} {
		if bytes.Contains(body, []byte(forbidden)) {
			t.Fatalf("empty collection serialised as null (%s):\n%s", forbidden, body)
		}
	}
	if !bytes.Contains(body, []byte(`"log_channel_id":null`)) || !bytes.Contains(body, []byte(`"role_id":null`)) {
		t.Fatalf("nullable ids must serialise as null:\n%s", body)
	}
	if !bytes.Contains(body, []byte(`"color":null`)) {
		t.Fatalf("dm_embed.color must serialise as null:\n%s", body)
	}
}

// TestModerationGet_ForceTrue 🛡️ — the `?force=true` query is parsed and forwarded
// to the repo's FindModule (mirrors the Node controller's
// `querySkipCacheValidation` → `findModule({ force })`).
func TestModerationGet_ForceTrue(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		FindModuleFn: func(_, _ string, force bool) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			if !force {
				t.Fatalf("force = false, want true (query not propagated)")
			}
			return moderationSourced(mocks.NewModuleModeration(), "db", "mongo.guild.module_moderation"), nil
		},
	}
	app := newModerationMockApp(repo)
	status, _, body := doModuleReq(t, app, "GET", "/bots/b1/guilds/g1/modules/moderation/?force=true", "Bearer "+testSecret, nil)
	if status != 200 {
		t.Fatalf("status = %d, want 200\nbody: %s", status, body)
	}
	if !repo.LastForce {
		t.Fatalf("repo.LastForce = false, want true (force not forwarded)")
	}
}

// TestModerationGet_SourceAttribution 🛡️ — a cache hit propagates source=cache and
// the module cache detail into both the header and the body.
func TestModerationGet_SourceAttribution(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		FindModuleFn: func(string, string, bool) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return moderationSourced(mocks.NewModuleModeration(), "cache", "redis:cache.db.module"), nil
		},
	}
	app := newModerationMockApp(repo)
	status, hdr, body := doModuleReq(t, app, "GET", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, nil)
	if status != 200 {
		t.Fatalf("status = %d, want 200\nbody: %s", status, body)
	}
	if got := hdr.Get(handlers.HeaderResultSource); got != "cache" {
		t.Fatalf("X-Result-Source = %q, want cache", got)
	}
	if got := hdr.Get(handlers.HeaderResultSourceDetail); got != "redis:cache.db.module" {
		t.Fatalf("X-Result-Source-Detail = %q, want redis:cache.db.module", got)
	}
}

// TestModerationGet_NotFound_DataNull 🛡️ — a repo Sourced with schema_version=0
// (guild missing) yields 400 MODULE_NOT_FOUND, source stamped from the repo, and
// an explicit `"data":null` (the data:null parity rule).
func TestModerationGet_NotFound_DataNull(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		FindModuleFn: func(string, string, bool) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return moderationSourced(dbguild.ModuleModeration{}, "db", "mongo.guild.module_moderation"), nil
		},
	}
	app := newModerationMockApp(repo)
	status, hdr, body := doModuleReq(t, app, "GET", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, nil)
	if status != 400 {
		t.Fatalf("status = %d, want 400\nbody: %s", status, body)
	}
	if !bytes.Contains(body, []byte("MODULE_NOT_FOUND")) {
		t.Fatalf("body should contain MODULE_NOT_FOUND: %s", body)
	}
	if !bytes.Contains(body, []byte(`"data":null`)) {
		t.Fatalf("not-found body must carry data:null (parity rule): %s", body)
	}
	if got := hdr.Get(handlers.HeaderResultSource); got != "db" {
		t.Fatalf("X-Result-Source = %q, want db (stamped even on not-found)", got)
	}
}

// TestModerationGet_RepoError_500 🛡️ — a repo error surfaces as 500 SYSTEM.
func TestModerationGet_RepoError_500(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		FindModuleFn: func(string, string, bool) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return nil, errors.New("db down")
		},
	}
	app := newModerationMockApp(repo)
	status, hdr, body := doModuleReq(t, app, "GET", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, nil)
	if status != 500 {
		t.Fatalf("status = %d, want 500\nbody: %s", status, body)
	}
	if got := hdr.Get(handlers.HeaderErrorType); got != "SYSTEM" {
		t.Fatalf("x-error-type = %q, want SYSTEM", got)
	}
}

// TestModerationPatch_Success 🛡️ — a present scalar is forwarded to the repo and
// the merged doc comes back 200.
func TestModerationPatch_Success(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		UpdateFn: func(_, _ string, _ map[string]any) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			d := mocks.NewModuleModeration()
			d.Enabled = true
			return moderationSourced(d, "db", "mongo.guild.module_moderation"), nil
		},
	}
	app := newModerationMockApp(repo)
	status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, map[string]any{"enabled": true})
	if status != 200 {
		t.Fatalf("status = %d, want 200\nbody: %s", status, body)
	}
	if len(repo.UpdateCalls) != 1 {
		t.Fatalf("UpdateCalls = %d, want 1", len(repo.UpdateCalls))
	}
	if enabled, ok := repo.UpdateCalls[0]["enabled"].(bool); !ok || !enabled {
		t.Fatalf("UpdateCalls[0][enabled] = %v, want true", repo.UpdateCalls[0]["enabled"])
	}
	var env struct {
		Data struct {
			Enabled bool `json:"enabled"`
		} `json:"data"`
	}
	if err := json.Unmarshal(body, &env); err != nil {
		t.Fatalf("unmarshal: %v\nbody: %s", err, body)
	}
	if !env.Data.Enabled {
		t.Fatalf("data.enabled = false, want true")
	}
}

// TestModerationPatch_NestedAndNullableForwarded 🛡️ — the raw JSON patch is
// forwarded field-for-field, preserving nested objects and omitting absent keys.
func TestModerationPatch_NestedAndNullableForwarded(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		UpdateFn: func(_, _ string, _ map[string]any) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return moderationSourced(mocks.NewModuleModeration(), "db", "mongo.guild.module_moderation"), nil
		},
	}
	app := newModerationMockApp(repo)
	status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret,
		map[string]any{
			"command_mode":   "slash",
			"log_channel_id": "chan-1",
			"mute":           map[string]any{"mode": "role"},
			"commands":       map[string]any{"ban": map[string]any{"enabled": true}},
			"automod":        map[string]any{"mentions": map[string]any{"max_mentions": 5}},
		})
	if status != 200 {
		t.Fatalf("status = %d, want 200\nbody: %s", status, body)
	}
	if len(repo.UpdateCalls) != 1 {
		t.Fatalf("UpdateCalls = %d, want 1", len(repo.UpdateCalls))
	}
	got := repo.UpdateCalls[0]
	if got["log_channel_id"] != "chan-1" {
		t.Fatalf("patch[log_channel_id] = %v, want chan-1", got["log_channel_id"])
	}
	if got["command_mode"] != "slash" {
		t.Fatalf("patch[command_mode] = %v, want slash", got["command_mode"])
	}
	mute, ok := got["mute"].(map[string]any)
	if !ok || mute["mode"] != "role" {
		t.Fatalf("patch[mute] = %v, want map[mode:role]", got["mute"])
	}
	if _, ok := mute["role_id"]; ok {
		t.Fatalf("patch[mute][role_id] unexpectedly present: %+v", mute)
	}
	commands, ok := got["commands"].(map[string]any)
	ban, banOK := commands["ban"].(map[string]any)
	if !ok || !banOK || ban["enabled"] != true {
		t.Fatalf("patch[commands] = %v, want ban.enabled=true", got["commands"])
	}
	automod, ok := got["automod"].(map[string]any)
	mentions, mentionsOK := automod["mentions"].(map[string]any)
	if !ok || !mentionsOK || mentions["max_mentions"] != float64(5) {
		t.Fatalf("patch[automod] = %v, want mentions.max_mentions=5", got["automod"])
	}
	for _, key := range []string{"enabled", "track_native_actions"} {
		if _, ok := got[key]; ok {
			t.Fatalf("patch[%s] unexpectedly present in raw JSON patch: %+v", key, got)
		}
	}
