	Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
}

// ─── Business-rule validation (server-side, NOT covered by the strict decode) ──
//
// The strict `UpdateModuleModerationBody` decode only checks SHAPE (known
// keys, right JSON type per field) — exactly like every other Go module body.
// The dashboard's zod layer additionally enforces which ENUM values are
// meaningful (`z.enum([...])` never accepts `""`), but that is CLIENT
// validation: a caller with a bearer token reaches this PATCH directly and an
// empty or unknown enum sails through the strict decode (an empty string is a
// perfectly valid Go `string`). The bot then reads that field at runtime,
// fails to match any of its known cases, and silently does nothing — while
// the stored document looks "configured" (the block is `enabled`, the rule
// has params, an escalation rung has a `threshold`) with no reader-visible
// sign that its `action`/`punishment`/`type` is empty or bogus.
//
// ValidateModerationPatch closes that gap by re-walking the SAME raw JSON
// patch map the handler forwards to the repo (so partial nested updates that
// never touch an enum key are left alone — no false positive on a legitimate
// `{"mute":{"role_id":"..."}}} that never mentions `mode`) and rejecting the
// impossible: a key that's PRESENT and either empty or not one of the values
// the bot actually knows how to act on. It deliberately does NOT re-enforce
// zod's numeric preferences (`min`/`max` on thresholds, windows, percentages)
// — those are recommendations, not configurations the bot literally cannot
// carry out, and duplicating them here would be a third copy of rules that
// already live in `moderation-schema.ts` (see the caveats on
// `UpdateModuleModerationBody` above).
func ValidateModerationPatch(patch map[string]any) *apierrors.CustomError {
	if v, ok := patch["command_mode"]; ok {
		if verr := requireModerationEnum(v, moderationCommandModeSet, moderationCommandModeMsg, "command_mode"); verr != nil {
			return verr
		}
	}
	if mute, ok := asModerationMap(patch["mute"]); ok {
		if v, present := mute["mode"]; present {
			if verr := requireModerationEnum(v, moderationMuteModeSet, moderationMuteModeMsg, "mute.mode"); verr != nil {
				return verr
			}
		}
	}
	if automod, ok := asModerationMap(patch["automod"]); ok {
		for _, rule := range moderationAutomodRuleKeys {
			ruleMap, ok := asModerationMap(automod[rule])
			if !ok {
				continue
			}
			if v, present := ruleMap["action"]; present {
				if verr := requireModerationEnum(v, automodActionSet, automodActionMsg, "automod."+rule+".action"); verr != nil {
					return verr
				}
			}
		}
	}
	if escalation, ok := asModerationMap(patch["escalation"]); ok {
		if countTypes, ok := asModerationSlice(escalation["count_types"]); ok {
			for i, v := range countTypes {
				property := fmt.Sprintf("escalation.count_types.%d", i)
				if verr := requireModerationEnum(v, infractionCountableTypeSet, infractionCountableTypeMsg, property); verr != nil {
					return verr
				}
			}
		}
		if rules, ok := asModerationSlice(escalation["rules"]); ok {
			for i, raw := range rules {
				rule, ok := asModerationMap(raw)
				if !ok {
					continue
				}
				property := fmt.Sprintf("escalation.rules.%d.action", i)
				v, present := rule["action"]
				if !present {
					v = ""
				}
				if verr := requireModerationEnum(v, moderationEscalationActionSet, moderationEscalationActionMsg, property); verr != nil {
					return verr
				}
			}
		}
	}
	if raid, ok := asModerationMap(patch["raid"]); ok {
		if v, present := raid["action"]; present {
			if verr := requireModerationEnum(v, moderationRaidActionSet, moderationRaidActionMsg, "raid.action"); verr != nil {
				return verr
			}
		}
	}
	if gate, ok := asModerationMap(patch["gate"]); ok {
		if v, present := gate["action"]; present {
			if verr := requireModerationEnum(v, moderationGateActionSet, moderationGateActionMsg, "gate.action"); verr != nil {
				return verr
			}
		}
	}
	if antinuke, ok := asModerationMap(patch["antinuke"]); ok {
		if v, present := antinuke["punishment"]; present {
			if verr := requireModerationEnum(v, moderationNukePunishmentSet, moderationNukePunishmentMsg, "antinuke.punishment"); verr != nil {
				return verr
			}
		}
		if limits, ok := asModerationMap(antinuke["limits"]); ok {
			for key, raw := range limits {
				limit, ok := asModerationMap(raw)
				if !ok {
					continue
				}
				if v, present := limit["punishment"]; present {
					property := "antinuke.limits." + key + ".punishment"
					if verr := requireModerationEnum(v, moderationNukePunishmentOrInheritSet, moderationNukePunishmentOrInheritMsg, property); verr != nil {
						return verr
					}
				}
			}
		}
	}
	if flows, ok := asModerationSlice(patch["flows"]); ok {
		for i, raw := range flows {
			flow, ok := asModerationMap(raw)
			if !ok {
				continue
			}
			if verr := validateModerationFlow(flow, "flows."+strconv.Itoa(i)); verr != nil {
				return verr
			}
		}
	}
